```js
const SCHEMA = {
  type: 'object',
  properties: {
    text: { type: 'string' },
    mode: { type: 'string', enum: ['uppercase', 'lowercase', 'slug'] },
    trim: { type: 'boolean' },
  },
  required: ['text', 'mode'],
  additionalProperties: false,
};

export async function listTools() {
  return [
    {
      name: 'text_transform',
      description: 'Transform text by case or slugify.',
      inputSchema: SCHEMA,
    },
  ];
}

function validate(args, schema) {
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }
  for (const key of Object.keys(args)) {
    if (!(key in schema.properties)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  for (const key of schema.required) {
    if (!(key in args)) {
      throw new Error(`Missing required argument: ${key}`);
    }
  }
  for (const [key, value] of Object.entries(args)) {
    const prop = schema.properties[key];
    if (prop.type === 'string' && typeof value !== 'string') {
      throw new Error(`Argument ${key} must be a string`);
    }
    if (prop.type === 'boolean' && typeof value !== 'boolean') {
      throw new Error(`Argument ${key} must be a boolean`);
    }
    if (prop.enum && !prop.enum.includes(value)) {
      throw new Error(`Argument ${key} must be one of ${prop.enum.join(', ')}`);
    }
  }
}

function transform(text, mode, trim) {
  if (mode === 'uppercase') {
    return (trim ? text.trim() : text).toUpperCase();
  }
  if (mode === 'lowercase') {
    return (trim ? text.trim() : text).toLowerCase();
  }
  // slug
  let s = text.toLowerCase();
  if (trim) s = s.trim();
  s = s.replace(/[^a-z0-9]+/g, '-');
  s = s.replace(/^-+|-+$/g, '');
  return s;
}

export async function callTool(name, args = {}) {
  if (name !== 'text_transform') {
    throw new Error(`Unknown tool: ${name}`);
  }
  validate(args, SCHEMA);
  const trim = args.trim === undefined ? true : args.trim;
  const result = transform(args.text, args.mode, trim);
  return { content: [{ type: 'text', text: result }] };
}
```

